  const tasks=[{text:'Purane orders, security boundary aur queue mein rakha email intent bache rahe',check:original},{text:'Asli source se bana private orders-reader available; primary alag aur bina badle',check:s=>{const r=s.account.rds.find(r=>r.id==='orders-reader');return s.account.rds.length===2&&r?.source==='orders'&&r.state==='available'&&r.resourceId!=='db-original-orders'&&!r.publicAccess&&r.encrypted&&same(r.dataFixture,initial.rds[0].dataFixture);}},{text:'Model mein 12–15 healthy private workers, teen AZ mein barabar; max ≤18',check:capacity},{text:'Review kiya aage ka up/down schedule metadata; abhi ki capacity alag se garam rakhi',check:schedules},{text:'Purane function ka reserved 20 aur purani enabled SQS mapping ka maximum 20',check:budget},{text:'Review kiya p95 alarm aur diye 3 periods ka taaza poora read: ALARM, green SLO ka daava nahi',check:alarmReady},{text:'Asli haath se bheja READINESS_TEST purane SNS topic se gaya aur purani ops queue se mila',check:routeProof}];
